/* Gemini AI table readability; teaching content and scripts are preserved. */
.lesson-body .core-table-scroll,.lesson-body .table-scroll {
 max-width:100%; overflow-x:auto; margin:24px 0;
 border:1px solid #BACBD8; border-radius:6px; background:#FCFDFE;
 overscroll-behavior-x:contain; -webkit-overflow-scrolling:touch;
 scrollbar-width:auto; scrollbar-color:#71889C #EEF3F9;
}
.lesson-body .core-table-scroll::-webkit-scrollbar,.lesson-body .table-scroll::-webkit-scrollbar { height:10px; }
.lesson-body .core-table-scroll::-webkit-scrollbar-track,.lesson-body .table-scroll::-webkit-scrollbar-track { background:#EEF3F9; }
.lesson-body .core-table-scroll::-webkit-scrollbar-thumb,.lesson-body .table-scroll::-webkit-scrollbar-thumb { background:#71889C; border:2px solid #EEF3F9; border-radius:6px; }
.lesson-body table:not(.heatmap-table) {
 width:100%; max-width:none; border-collapse:collapse; border-spacing:0;
 font-size:1rem; line-height:1.75; background:#FCFDFE;
}
.lesson-body table:not(.heatmap-table) th,.lesson-body table:not(.heatmap-table) td {
 padding:14px 16px; border:1px solid #BACBD8;
 text-align:left; vertical-align:top; word-break:normal; overflow-wrap:anywhere;
}
.lesson-body table:not(.heatmap-table) th { background:#EEF3F9; color:#173B57; font-weight:700; }
.lesson-body table:not(.heatmap-table) td { color:#344552; }
.lesson-body table:not(.heatmap-table) tbody tr:nth-child(even)>td { background:#F4F8FC; }
.lesson-body table:not(.heatmap-table) tbody tr>td:first-child { font-weight:600; }
.lesson-body .core-table-scroll table { min-width:32rem; table-layout:fixed; }
.lesson-body .core-table-scroll table th:first-child { width:30%; }
.lesson-body .core-table-scroll table:has(thead>tr:first-child>th:nth-child(3)) { min-width:40rem; }
.lesson-body .core-table-scroll table:has(thead>tr:first-child>th:nth-child(3)) th:first-child { width:20%; }
.lesson-body .core-table-scroll table:has(thead>tr:first-child>th:nth-child(4)) { min-width:52rem; }
.lesson-body .core-table-scroll table:has(thead>tr:first-child>th:nth-child(5)) { min-width:48rem; }
.lesson-body .interview-table { width:max-content; min-width:100%; table-layout:auto; }
.lesson-body .interview-table .criteria-col { min-width:10rem; }
.lesson-body .interview-table th:not(:first-child),.lesson-body .interview-table td:not(:first-child) { min-width:14rem; }
.lesson-body .interview-table textarea { min-width:10rem; }
.lesson-body .history-table { min-width:42rem; }
.lesson-body .history-table td:nth-child(3) { white-space:normal!important; max-width:none!important; overflow-wrap:anywhere; }
/* Preserve the heat-state backgrounds and text colors; adjust only dimensions. */
.lesson-body table.heatmap-table { max-width:none; border-collapse:collapse; }
.lesson-body .heatmap-table th,.lesson-body .heatmap-table td.time-label {
 padding:12px; font-size:1rem; line-height:1.6; color:#344552; background:#EEF3F9;
 border:1px solid #BACBD8; white-space:nowrap;
}
.lesson-body .heatmap-table .heat-cell { min-width:76px; height:44px; padding:10px 12px; font-size:.9rem; line-height:1.6; }
@media(max-width:600px) {
 .lesson-body table:not(.heatmap-table) th,.lesson-body table:not(.heatmap-table) td { padding:12px 14px; }
}

