th {background:#EEF3F9;color:#173B57;font-weight:700}
td {color:#344552;background:#FCFDFE}
tbody tr:nth-child(even)>td {background:#F4F8FC}
td input,td select {min-width:90px}
td input[type=number] {text-align:right;font-variant-numeric:tabular-nums}
#available {min-width:360px}
#available th,#available td {min-width:90px;white-space:nowrap}
#result table {min-width:880px}
}
