course-palette.css:
/* Gemini AI course palette; original DOM and scripts retained. */
:root {
 --c-bg:#F7FAFC; --c-surface:#EEF3F9; --c-card:#FCFDFE;
 --c-border:#DEE7EF; --c-border-soft:#DEE7EF;
 --c-text:#344552; --c-muted:#586C80; --c-faint:#586C80;
 --c-main:#167D8D; --c-a1:#167D8D; --c-a2:#285C82;
 --c-a3:#236B69; --c-a4:#355E7C; --c-a5:#526786;
}
.topbar { background:rgba(247,250,252,.97); }
.logo { color:#173B57; }
h1,h2,h3,h4,.hero-title,.lesson-title,.section-heading,.part-title,
.lesson-title,.next-card-name,.category-label,.nav-btn-title,
.stat-num,.outcomes-label,.step-title,.demo-flow-label {
 font-family:'Noto Sans TC',sans-serif; color:#173B57;
}
.section-heading em { color:inherit; }
.topbar-tag { color:#126775; background:#E7F5F4; border-color:#167D8D; }
.hero-eyebrow,.hero-num,.chapter-label,.chapter-open,.resource-action,
.case-arrow,.case-open,.prac-label,.prac-num,.prac-num-5 {
 color:#167D8D;
}
.hero-divider,.progress-fill,.prog-fill { background:#167D8D; }
.course-entry h2,.lesson-body h2,.case-group-heading h2 { color:#173B57; }
.lesson-body a,.supplement-list a,.entry-materials a,#choose-case>p a {
 color:#126775; text-underline-offset:4px;
}
.back-link:hover,.topbar-search:hover,.back-to-categories:hover { color:#116775; }
.entry-start { background:#167D8D; border-color:#167D8D; color:#FCFDFE; }
.entry-start:hover { background:#116775; opacity:1; }
.entry-outline { color:#173B57; border-color:#71889C; }
.entry-outline:hover,.chapter-link:hover,.resource-link:hover,.category-link:hover,
.case-link:hover,.nav-btn:hover { border-color:#167D8D; background:#E7F5F4; }
.chapter-link h3,.resource-link h3,.case-link h3 { color:#173B57; }
.chapter-open,.case-open { border-top-color:#DEE7EF; }
.case-level { border-color:#71889C; color:#344552; background:#F7FAFC; }
.entry-reference { background:#FCFDFE; }
.entry-reference>summary { color:#173B57; }
.entry-reference[open]>summary { background:#EEF3F9; border-radius:6px 6px 0 0; }
.reference-group h3 { color:#173B57; }
.compare-card.highlight { border-color:#167D8D; background:#E7F5F4; }
.callout.info { background:#EEF3F9; border-left-color:#285C82; }
.callout.tip,.callout.key { background:#E7F5F4; border-left-color:#236B69; }
.callout.warning,.callout.warn { background:#FFF3DF; border-left-color:#996018; }
.callout.error,.callout.danger { background:#FFF0ED; border-left-color:#A43E35; }
.prompt-wrap,.prompt-box,.policy-case,.case-data,.dialog-box {
 background:#EEF3F9; border-color:#DEE7EF; color:#344552;
}
.prompt-label,.prompt-header,.dialog-label { color:#126775; }
.inline-code { background:#E7F5F4; color:#126775; }
.copy-btn,.btn-drill-copy,.radar-add-btn,.btn-add {
 color:#126775; border-color:#167D8D; background:#FCFDFE;
}
.copy-btn:hover,.btn-drill-copy:hover,.radar-add-btn:hover,.btn-add:hover {
 color:#116775; background:#E7F5F4;
}
.compose-btn,.radar-gen-btn,.btn-render { background:#167D8D; color:#FCFDFE; }
.compose-btn:hover,.radar-gen-btn:hover,.btn-render:hover {
 background:#116775; opacity:1;
}
.tool-topbar { background:#EEF3F9; border-bottom-color:#DEE7EF; }
.lesson-body input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]),
.lesson-body textarea,.lesson-body select {
 background:#FCFDFE; color:#344552; border-color:#71889C;
}
.lesson-body input::placeholder,.lesson-body textarea::placeholder { color:#586C80; }
.lesson-body input[type=checkbox],.lesson-body input[type=radio] { accent-color:#167D8D; }
.lesson-body input:focus,.lesson-body textarea:focus,.lesson-body select:focus {
 border-color:#167D8D;
}
.core-table-scroll th { background:#EEF3F9; color:#173B57; }
.core-table-scroll td { color:#344552; }
.sdot.active { background:#167D8D; }
body #_gate { background:#F7FAFC; }
body #_gate-box { background:#FCFDFE; border-color:#DEE7EF; }
body #_gate-title { font-family:'Noto Sans TC',sans-serif; color:#173B57; }
body #_gate-sub { color:#586C80; }
body #_gate-input { background:#FCFDFE; color:#344552; border-color:#71889C; }
body #_gate-input:focus { border-color:#167D8D; background:#FCFDFE; }
body #_gate-btn { background:#167D8D; color:#FCFDFE; }
body #_gate-btn:hover { background:#116775; }
body #_gate-err { color:#9C4420; }
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,
select:focus-visible,summary:focus-visible,[tabindex]:focus-visible,
.entry-start:focus-visible,.entry-outline:focus-visible,.chapter-link:focus-visible,
.resource-link:focus-visible,.case-link:focus-visible,.category-link:focus-visible,
.back-to-categories:focus-visible,.supplement-list a:focus-visible {
 outline:3px solid #167D8D; outline-offset:4px;
}
@media(prefers-reduced-motion:reduce) {
 html { scroll-behavior:auto; }
 *,*::before,*::after { transition:none!important; animation:none!important; }
}

prompt-layout.css:
/* Shared prompt spacing and type hierarchy; lesson text and colors retained. */
.lesson-body .prompt-wrap {
 box-sizing:border-box; min-width:0; padding:24px;
 border:1px solid var(--c-border); border-radius:var(--radius,8px);
}
.lesson-body .prompt-wrap .prompt-label {
 margin:0 0 10px; font-size:1rem; font-weight:700;
 line-height:1.6; letter-spacing:.02em;
}
.lesson-body .prompt-wrap > .prompt-header {
 padding:0; margin:0; border:0; background:transparent;
}
.lesson-body .prompt-wrap > .policy-guide {
 margin:0 0 16px; font-size:.875rem; line-height:1.8;
}
.lesson-body .prompt-wrap > pre {
 box-sizing:border-box; margin:0; padding:16px 18px;
 max-width:100%; white-space:pre-wrap; overflow-wrap:anywhere;
}
.lesson-body .prompt-wrap > .policy-copy-row { margin:16px 0 0; }
.lesson-body .prompt-wrap > .copy-btn { margin-top:16px; min-height:44px; }
@media(max-width:600px) {
 .lesson-body .prompt-wrap { padding:18px 16px; }
 .lesson-body .prompt-wrap > pre { padding:14px; }
}

result-palette.css:
/* Generated tool/prompt output uses the same readable course surface. */
.lesson-body .result-box {
 background:#EEF3F9; color:#344552; border-color:#DEE7EF;
}
.lesson-body .result-label {
 color:#126775; font-size:1rem; font-weight:700;
 line-height:1.6; letter-spacing:.02em;
}

reading-lists.css:
/* Reading lists use the same scale as lesson body text. */
.lesson-body .step-list {
 font-size:.92rem; font-weight:400; line-height:1.95;
 padding-inline-start:1.5em; margin:0 0 20px;
}
.lesson-body .step-list li { margin-bottom:8px; }
.lesson-body .step-list a { font-size:inherit; font-weight:inherit; }
